#include <iostream>
#include <vector>
using namespace std;
long long mergeCount(vector<long long>& arr, int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) / 2;
    long long cnt = mergeCount(arr, lo, mid) + mergeCount(arr, mid, hi);
    // Write merge step here
    return cnt;
}
int main() {
    int n; cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    cout << mergeCount(a, 0, n) << '\n';
    return 0;
}

