import java.util.*;
import java.io.*;
public class Main {
    static long mergeCount(long[] arr, int lo, int hi) {
        if (hi - lo <= 1) return 0;
        int mid = (lo + hi) / 2;
        long cnt = mergeCount(arr, lo, mid) + mergeCount(arr, mid, hi);
        // Write merge step here
        return cnt;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = Long.parseLong(st.nextToken());
        System.out.println(mergeCount(a, 0, n));
    }
}
